import { defineConfig } from 'vite'
import { resolve } from 'path'
import { fileURLToPath } from 'node:url'
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'

const UNOFF = fileURLToPath(new URL('./node_modules/@unoff/ui/dist/assets', import.meta.url))

// Yelbolt brand (same rules as SplineXR): Unoff UI component tokens (button, input,
// card…) for the Yelbolt theme, without the components themselves — their stylesheets
// also hold class rules that would clash with ours (.card…). Only the custom-property
// blocks of the Yelbolt theme are kept, in a generated file (not versioned).
const COMPONENTS = ['Button', 'Input', 'card', 'Chip', 'SegmentedControl', 'SemanticMessage',
  'SectionTitle', 'Section', 'Thumbnail', 'Tooltip', 'Message', 'form-item', 'list', 'SimpleItem',
  'Bar', 'Drawer', 'Dropzone', 'Dropdown', 'SimpleSlider', 'styles/texts/texts']
function unoffComponentTokens() {
  const out = fileURLToPath(new URL('./src/styles/unoff-yelbolt-components.generated.css', import.meta.url))
  const generate = () => {
    let css = '/* Generated by vite.config.js from @unoff/ui: Yelbolt component tokens. Do not edit. */\n'
    for (const name of COMPONENTS) {
      const src = readFileSync(`${UNOFF}/${name}.css`, 'utf8')
      const blocks = src.match(/(?::root)?\[data-theme=yelbolt\]\{[^{}]*\}/g) ?? []
      for (const b of blocks) if (/^[^{]*\{\s*--/.test(b)) css += `/* ${name} */\n${b}\n`
    }
    mkdirSync(fileURLToPath(new URL('./src/styles', import.meta.url)), { recursive: true })
    writeFileSync(out, css)
  }
  return { name: 'unoff-yelbolt-component-tokens', config: generate }
}

// URLs without a trailing slash (/musee, /creer/filtre…) → their index.html, like the
// 200 rules of public/_redirects on Netlify. For `vite` and `vite preview`.
const PAGES = ['/musee', '/musee/affiches', '/filtre', '/creer', '/creer/musee', '/creer/filtre']
const prettyUrls = {
  name: 'pretty-urls',
  configureServer(server) { server.middlewares.use(rewrite) },
  configurePreviewServer(server) { server.middlewares.use(rewrite) },
}
function rewrite(req, _res, next) {
  const [path, query = ''] = req.url.split('?')
  if (PAGES.includes(path)) req.url = `${path}/index.html${query ? '?' + query : ''}`
  next()
}

export default defineConfig({
  plugins: [unoffComponentTokens(), prettyUrls],
  resolve: {
    alias: {
      three: 'super-three',
      // Unoff UI design tokens (CSS only; the package exports React components only,
      // so its stylesheets are reached by path)
      '@unoff-styles': `${UNOFF}/styles`,
    },
  },
  build: {
    target: 'es2022', // top-level await (i18n is loaded before the page renders)
    chunkSizeWarningLimit: 4000,
    rollupOptions: {
      input: {
        home: resolve(__dirname, 'index.html'),
        museum: resolve(__dirname, 'musee/index.html'),
        filter: resolve(__dirname, 'filtre/index.html'),
        create: resolve(__dirname, 'creer/index.html'),
        createMuseum: resolve(__dirname, 'creer/musee/index.html'),
        createFilter: resolve(__dirname, 'creer/filtre/index.html'),
        posters: resolve(__dirname, 'musee/affiches/index.html'),
      },
    },
  },
})
